class Solution {
public:
    int removeStones(vector<vector<int>>& stones) {
        unordered_map<int, int> parent;
        auto find = [&](auto& self, int x) -> int {
            if (!parent.count(x)) parent[x] = x;
            if (parent[x] != x) parent[x] = self(self, parent[x]);
            return parent[x];
        };
        auto unite = [&](int x, int y) {
            int rx = find(find, x), ry = find(find, y);
            if (rx != ry) parent[rx] = ry;
        };
        for (const auto& s : stones) {
            unite(s[0], ~s[1]);
        }
        unordered_set<int> comps;
        for (const auto& [node, _] : parent) {
            comps.insert(find(find, node));
        }
        return (int)stones.size() - (int)comps.size();
    }
};

class Solution {
    private Map<Integer, Integer> parent = new HashMap<>();

    private int find(int x) {
        parent.putIfAbsent(x, x);
        if (parent.get(x) != x) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }

    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) {
            parent.put(rx, ry);
        }
    }

    public int removeStones(int[][] stones) {
        for (int[] s : stones) {
            union(s[0], ~s[1]);
        }
        Set<Integer> comps = new HashSet<>();
        for (int node : parent.keySet()) {
            comps.add(find(node));
        }
        return stones.length - comps.size();
    }
}

var removeStones = function(stones) {
    const parent = new Map();
    const find = (x) => {
        if (!parent.has(x)) parent.set(x, x);
        if (parent.get(x) !== x) {
            parent.set(x, find(parent.get(x)));
        }
        return parent.get(x);
    };
    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent.set(rx, ry);
    };
    for (const [r, c] of stones) {
        union(r, ~c);
    }
    const comps = new Set();
    for (const node of parent.keys()) {
        comps.add(find(node));
    }
    return stones.length - comps.size;
};
